//! Final combined gate only; fictional records and real native PostgreSQL locking.
async fn execution_running(c:&mut PgConnection)->Value{let mut config=execution_seed_policy(c).await;config["state"]=json!("RUNNING");browser_save(c,"application_queue_policy",config.clone()).await;browser_save(c,"exec_config:naukri",json!({"mode":"ON_DEMAND"})).await;config}
async fn execution_enqueue(c:&mut PgConnection,number:&str)->Value{automated_apply_agents::execution::queue::enqueue(c,&format!("https://www.naukri.com/job-listings-fictional-{number}"),"saved_verified_job",Some("fictional-reference")).await.unwrap()}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_enqueue_permanent_identity_retains_unknown_work_and_refuses_damaged_receipt_replay(){
    let mut c=browser_fixture().await;execution_seed_policy(&mut c).await;let work=execution_enqueue(&mut c,"123456789012").await;let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut unknown=work.clone();unknown["stage"]=json!("SUBMISSION_UNKNOWN");unknown["status"]=json!("unknown");unknown["admitted_actions"]=json!([{"fingerprint":"apply:spent"}]);browser_save(&mut c,&key,unknown.clone()).await;let repeated=automated_apply_agents::execution::queue::enqueue(&mut c,"https://www.naukri.com/job-listings-different-slug-123456789012/","saved_verified_job",None).await.unwrap();assert_eq!(repeated,unknown);
    browser_save(&mut c,"naukri_worker_receipt:223456789012",json!({"damaged":true})).await;assert_eq!(automated_apply_agents::execution::queue::enqueue(&mut c,"https://www.naukri.com/job-listings-fictional-223456789012","saved_verified_job",None).await.unwrap_err(),Failure("prior_receipt_requires_reconciliation_no_replay"));let before=browser_snapshot(&mut c).await;assert_eq!(automated_apply_agents::execution::queue::enqueue(&mut c,"https://www.naukri.com/job-listings-fictional-323456789012","unapproved-mail-source",None).await.unwrap_err(),Failure("unsupported_queue_source"));assert_eq!(browser_snapshot(&mut c).await,before);assert!(!work.to_string().contains("fictional-reference"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_claim_concurrent_pollers_obtain_one_durable_lease_without_returning_closed_history(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let expected=execution_enqueue(&mut c,"123456789012").await;let _=execution_enqueue(&mut c,"223456789012").await;let mut other=connection().await;let binding=json!({"worker":"local_preparation"});let(a,b)=tokio::join!(automated_apply_agents::execution::queue::claim(&mut c,"naukri",&binding,None),automated_apply_agents::execution::queue::claim(&mut other,"naukri",&binding,None));let a=a.unwrap();let b=b.unwrap();assert_eq!(usize::from(a.is_some())+usize::from(b.is_some()),1);let lease=a.or(b).unwrap();assert_eq!(lease["id"],expected["id"]);assert_eq!(lease["status"],"leased");assert_eq!(lease["attempts"],1);assert_eq!(lease["policy_revision"],162);assert!(lease["lease_token"].as_str().unwrap().parse::<Uuid>().is_ok());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_event:') AND value->>'event'='claimed'").fetch_one(&mut c).await.unwrap(),1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_claim_recovers_every_expired_write_even_when_a_different_live_lease_blocks_poll(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let first=execution_enqueue(&mut c,"123456789012").await;let second=execution_enqueue(&mut c,"223456789012").await;
    let mut live=first.clone();live["status"]=json!("leased");live["lease_until"]=json!("2099-01-01T00:00:00Z");browser_save(&mut c,&format!("apply_work:{}",first["id"].as_str().unwrap()),live).await;let mut expired=second.clone();expired["operation"]=json!("apply");expired["stage"]=json!("APPLYING");expired["status"]=json!("executing");expired["lease_until"]=json!("2020-01-01T00:00:00Z");expired["admitted_actions"]=json!([{"fingerprint":"apply:spent","at":"2020-01-01T00:00:00Z"}]);let key=format!("apply_work:{}",second["id"].as_str().unwrap());browser_save(&mut c,&key,expired.clone()).await;
    assert!(automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"local_preparation"}),None).await.unwrap().is_none());let unknown=browser_pref(&mut c,&key).await;assert_eq!(unknown["status"],"unknown");assert_eq!(unknown["stage"],"SUBMISSION_UNKNOWN");assert_eq!(unknown["admitted_actions"],expired["admitted_actions"]);assert!(unknown["lease_token"].is_null());
}
