    let mut c=browser_fixture().await;execution_running(&mut c).await;let mut work=execution_enqueue(&mut c,"123456789012").await;work["operation"]=json!("apply");work["status"]=json!("leased");work["lease_until"]=json!("2020-01-01T00:00:00Z");work["account_sha256"]=json!("a".repeat(64));browser_save(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap()),work).await;let claimed=automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"local_preparation"}),None).await.unwrap().unwrap();assert_eq!(claimed["operation"],"inspect_profile");assert_eq!(claimed["stage"],"FAILED_RETRYABLE");assert_eq!(claimed["status"],"leased");assert_eq!(claimed["admitted_actions"],json!([]));
