#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_claim_fairness_and_operation_filter_do_not_bypass_policy_or_consume_a_write(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let first=execution_enqueue(&mut c,"123456789012").await;let mut second=execution_enqueue(&mut c,"223456789012").await;second["operation"]=json!("apply");let second_key=format!("apply_work:{}",second["id"].as_str().unwrap());browser_save(&mut c,&second_key,second.clone()).await;
    let read=automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"local_preparation"}),Some(&["inspect_job"])).await.unwrap().unwrap();assert_eq!(read["id"],first["id"]);assert_eq!(browser_pref(&mut c,&second_key).await["status"],"queued");assert_eq!(browser_pref(&mut c,&second_key).await["admitted_actions"],json!([]));
    let before=browser_snapshot(&mut c).await;let mut off=execution_seed_policy(&mut c).await;off["state"]=json!("RUNNING");off["policy"]["platforms"]["naukri"]["enabled"]=json!(false);browser_save(&mut c,"application_queue_policy",off).await;assert!(automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"local_preparation"}),None).await.unwrap().is_none());assert_eq!(browser_pref(&mut c,&second_key).await,before[&second_key]);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_read_admission_rechecks_bound_lease_and_never_reserves_application_budget(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let _=execution_enqueue(&mut c,"123456789012").await;sqlx::raw_sql("CREATE TABLE IF NOT EXISTS agent_policies(key varchar(20) PRIMARY KEY,version integer NOT NULL,preferences jsonb NOT NULL);DELETE FROM agent_policies").execute(&mut c).await.unwrap();let binding=json!({"worker":"local_preparation"});let lease=automated_apply_agents::execution::queue::claim(&mut c,"naukri",&binding,None).await.unwrap().unwrap();let id=lease["id"].as_str().unwrap().parse().unwrap();let token=lease["lease_token"].as_str().unwrap().parse().unwrap();let revision=lease["revision"].as_i64().unwrap();let settings=packet_settings();let resumes=automated_apply_agents::private_resume::Settings::from_values(&host_values()).unwrap();let request=||automated_apply_agents::execution::admission::Request{identity:id,revision,token,binding:&binding};let services=||automated_apply_agents::execution::admission::Services{packets:&settings,resumes:&resumes};let admitted=automated_apply_agents::execution::admission::admit(&mut c,request(),services()).await.unwrap();assert_eq!(admitted["status"],"executing");assert_eq!(admitted["admitted_actions"],json!([]));assert_eq!(automated_apply_agents::execution::admission::admit(&mut c,request(),services()).await.unwrap_err(),Failure("queue_lease_lost"));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_admission_totals_count_three_spent_apply_jobs_across_midnight_and_unknown_outcomes(){
    let mut c=browser_fixture().await;let at=chrono::DateTime::parse_from_rfc3339("2026-11-16T01:00:00Z").unwrap().with_timezone(&chrono::Utc);
    for (i,date) in ["2026-11-01T02:00:00Z","2026-11-15T23:59:00Z","2026-11-16T00:30:00Z"].iter().enumerate(){let id=Uuid::new_v4();browser_save(&mut c,&format!("apply_work:{id}"),json!({"id":id,"platform":"naukri","stage":if i==2{"SUBMISSION_UNKNOWN"}else{"NEEDS_INPUT"},"admitted_actions":[{"fingerprint":"apply:initial","at":date},{"fingerprint":"answer_questionnaire:step-one","at":date}],"facts":{"description":"PRIVATE_FULL_HISTORY_MUST_STAY_IN_DB"}})).await;}
    let totals:Value=sqlx::query_scalar(include_str!("../../sql/execution_admission_totals.sql")).bind("naukri").bind(at).fetch_one(&mut c).await.unwrap();assert_eq!(totals,json!({"invalid":false,"lifetime_apply":3,"hourly_work":1}));assert_eq!(4-totals["lifetime_apply"].as_i64().unwrap(),1);assert!(!totals.to_string().contains("PRIVATE_FULL_HISTORY"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_admission_totals_malformed_missing_future_and_unrecognized_history_require_reconciliation(){
    let mut c=browser_fixture().await;let at=chrono::DateTime::parse_from_rfc3339("2026-11-16T01:00:00Z").unwrap().with_timezone(&chrono::Utc);let id=Uuid::new_v4();let key=format!("apply_work:{id}");
    let action=json!({"fingerprint":"apply:initial","at":"2026-11-16T00:30:00Z"});let good=json!({"id":id,"platform":"naukri","admitted_actions":[action.clone()]});let mut cases=vec![];
    for invalid in [Value::Null,json!("lost"),json!({"unknown":true}),json!([null]),json!([{}]),json!([{"fingerprint":"other:unknown","at":"2026-11-16T00:30:00Z"}]),json!([{"fingerprint":"apply:initial","at":"2026-11-16T02:00:00Z"}]),json!([{"fingerprint":"apply:initial","at":"invalid-time"}])]{let mut value=good.clone();value["admitted_actions"]=invalid;cases.push(value);}
    let mut missing=good.clone();missing.as_object_mut().unwrap().remove("admitted_actions");cases.push(missing);let mut bad_id=good.clone();bad_id["id"]=json!("missing-identity");cases.push(bad_id);let mut wrong_id=good.clone();wrong_id["id"]=json!(Uuid::new_v4());cases.push(wrong_id);let mut no_platform=good.clone();no_platform.as_object_mut().unwrap().remove("platform");cases.push(no_platform);
    for value in cases {browser_save(&mut c,&key,value.clone()).await;let totals:Value=sqlx::query_scalar(include_str!("../../sql/execution_admission_totals.sql")).bind("naukri").bind(at).fetch_one(&mut c).await.unwrap();assert_eq!(totals["invalid"],true,"{value}");assert_eq!(browser_pref(&mut c,&key).await,value);}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_admission_changed_mode_binding_token_or_expired_lease_cannot_create_a_budget_or_event(){
    let mut c=browser_fixture().await;execution_running(&mut c).await;let _=execution_enqueue(&mut c,"123456789012").await;sqlx::raw_sql("CREATE TABLE IF NOT EXISTS agent_policies(key varchar(20) PRIMARY KEY,version integer NOT NULL,preferences jsonb NOT NULL);DELETE FROM agent_policies").execute(&mut c).await.unwrap();let binding=json!({"worker":"local_preparation"});let lease=automated_apply_agents::execution::queue::claim(&mut c,"naukri",&binding,None).await.unwrap().unwrap();let settings=packet_settings();let resumes=automated_apply_agents::private_resume::Settings::from_values(&host_values()).unwrap();let id=lease["id"].as_str().unwrap().parse().unwrap();let token=lease["lease_token"].as_str().unwrap().parse().unwrap();let revision=lease["revision"].as_i64().unwrap();let key=format!("apply_work:{id}");
    for kind in ["token","binding","mode","expired"] {browser_save(&mut c,&key,lease.clone()).await;browser_save(&mut c,"exec_config:naukri",json!({"mode":if kind=="mode"{"OFF"}else{"ON_DEMAND"}})).await;if kind=="expired"{let mut expired=lease.clone();expired["lease_until"]=json!("2020-01-01T00:00:00Z");browser_save(&mut c,&key,expired).await;}let before=browser_snapshot(&mut c).await;let wrong=json!({"worker":"different-worker"});let request=automated_apply_agents::execution::admission::Request{identity:id,revision,token:if kind=="token"{Uuid::new_v4()}else{token},binding:if kind=="binding"{&wrong}else{&binding}};let error=automated_apply_agents::execution::admission::admit(&mut c,request,automated_apply_agents::execution::admission::Services{packets:&settings,resumes:&resumes}).await.unwrap_err();assert_eq!(error,Failure(if kind=="mode"{"execution_mode_off"}else{"queue_lease_lost"}));assert_eq!(browser_snapshot(&mut c).await,before);}
}
